WITH RECURSIVE x9 AS (SELECT 1 AS x12 UNION ALL SELECT 1 + x8.v45042 FROM x13 WHERE x8.v45043 < 100) SELECT x8.v45043, x8.v45043, ST_INTERSECTS(ST_GEOMFROMTEXT('GEOMETRYCOLLECTION(GEOMETRYCOLLECTION())'), ST_GEOMFROMTEXT('POINT(0 0)')) AS x4, x8.v45043 FROM v45041 AS x8 WHERE EXISTS(SELECT 1 FROM x10, x11 WHERE x8.v45042 = x8.v45042 AND MATCH(x8.v45043) AGAINST('scargill' IN BOOLEAN MODE))